import { useState } from "react";
import { MapPin, Phone, Mail, Clock, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { submitContact } from "@/lib/api";
import { SHOP } from "@/lib/shopInfo";

const INITIAL = { name: "", email: "", phone: "", message: "" };

const inputCls =
  "w-full bg-transparent border-b border-brand-border focus:border-brand-maroon focus:outline-none py-3 text-brand-text placeholder:text-brand-text/40 transition-colors";

function Detail({ icon, label, children, testId }) {
  return (
    <div
      className="flex gap-4 border-b border-brand-border pb-6 last:border-b-0"
      data-testid={testId}
    >
      <div className="h-10 w-10 rounded-full bg-brand-maroon/10 text-brand-maroon flex items-center justify-center shrink-0">
        {icon}
      </div>
      <div>
        <div className="text-[11px] tracking-[0.28em] uppercase text-brand-gold mb-1.5">
          {label}
        </div>
        <div className="text-brand-text/85 leading-relaxed text-sm">
          {children}
        </div>
      </div>
    </div>
  );
}

function Field({ label, required, optional, error, children, testId }) {
  return (
    <label className="block" data-testid={testId}>
      <span className="text-[11px] tracking-[0.25em] uppercase text-brand-text/70">
        {label}
        {required && <span className="text-brand-maroon"> *</span>}
        {optional && (
          <span className="text-brand-text/40 normal-case tracking-normal">
            {" "}(optional)
          </span>
        )}
      </span>
      <div className="mt-1">{children}</div>
      {error && (
        <span className="block mt-2 text-xs text-brand-maroon">
          {error}
        </span>
      )}
    </label>
  );
}

export default function ContactPage() {
  const [form, setForm] = useState(INITIAL);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  const update = (field) => (e) => {
    setForm((f) => ({ ...f, [field]: e.target.value }));
    if (errors[field]) setErrors((er) => ({ ...er, [field]: undefined }));
  };

  const validate = () => {
    const next = {};
    if (!form.name.trim()) next.name = "Please tell us your name.";
    if (!form.email.trim()) next.email = "We need an email to reach you.";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email))
      next.email = "That email doesn't look right.";
    if (!form.message.trim() || form.message.trim().length < 5)
      next.message = "A few more words, please.";
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setSubmitting(true);
    try {
      await submitContact({
        name: form.name.trim(),
        email: form.email.trim(),
        phone: form.phone.trim(),
        message: form.message.trim(),
      });
      toast.success("Message received — we will be in touch shortly.");
      setForm(INITIAL);
    } catch (err) {
      const detail =
        err?.response?.data?.detail ||
        "Could not send your message. Please try again.";
      toast.error(detail);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div data-testid="contact-page" className="bg-brand-ivory">
      <section className="bg-brand-cream border-b border-brand-border">
        <div className="max-w-7xl mx-auto px-6 lg:px-10 py-20 md:py-24 text-center">
          <span className="divider-ornament">Visit · Call · Write</span>
          <h1 className="font-serif text-brand-maroon text-5xl sm:text-6xl mt-5">
            Step into the shop
          </h1>
          <p className="mt-5 max-w-2xl mx-auto text-brand-text/75 leading-relaxed">
            Festive trays, bespoke hampers or simply directions to our counter
            — we'd be delighted to hear from you.
          </p>
        </div>
      </section>

      <section className="max-w-7xl mx-auto px-6 lg:px-10 py-20 grid lg:grid-cols-12 gap-12">
        <div className="lg:col-span-5 space-y-8">
          <Detail icon={<MapPin size={18} />} label="Our Address" testId="contact-address">
            {SHOP.addressLines.map((line) => (
              <span key={line} className="block">{line}</span>
            ))}
          </Detail>
          <Detail icon={<Phone size={18} />} label="Phone" testId="contact-phone">
            <a href={`tel:${SHOP.phone.replace(/\s/g, "")}`} className="block hover:text-brand-maroon">
              {SHOP.phone}
            </a>
            <a href={`tel:${SHOP.altPhone.replace(/\s/g, "")}`} className="block hover:text-brand-maroon">
              {SHOP.altPhone}
            </a>
          </Detail>
          <Detail icon={<Mail size={18} />} label="Email" testId="contact-email">
            <a href={`mailto:${SHOP.email}`} className="hover:text-brand-maroon">
              {SHOP.email}
            </a>
          </Detail>
          <Detail icon={<Clock size={18} />} label="Counter Hours" testId="contact-hours">
            {SHOP.hours.map((h) => (
              <span key={h.day} className="block">
                <span className="text-brand-text">{h.day}</span>
                <span className="text-brand-text/60"> · {h.time}</span>
              </span>
            ))}
          </Detail>
        </div>

        <div className="lg:col-span-7">
          <div className="bg-brand-cream border border-brand-border rounded-sm p-8 md:p-12">
            <span className="divider-ornament">Write to us</span>
            <h2 className="font-serif text-brand-maroon text-3xl sm:text-4xl mt-5">
              A note for the family
            </h2>
            <form className="mt-8 grid gap-6" onSubmit={handleSubmit} noValidate>
              <Field label="Name" required error={errors.name} testId="contact-name">
                <input
                  type="text"
                  value={form.name}
                  onChange={update("name")}
                  placeholder="Your full name"
                  className={inputCls}
                />
              </Field>
              <div className="grid sm:grid-cols-2 gap-6">
                <Field label="Email" required error={errors.email} testId="contact-email-field">
                  <input
                    type="email"
                    value={form.email}
                    onChange={update("email")}
                    placeholder="you@example.com"
                    className={inputCls}
                  />
                </Field>
                <Field label="Phone" optional error={errors.phone} testId="contact-phone-field">
                  <input
                    type="tel"
                    value={form.phone}
                    onChange={update("phone")}
                    placeholder="+91"
                    className={inputCls}
                  />
                </Field>
              </div>
              <Field label="Message" required error={errors.message} testId="contact-message-field">
                <textarea
                  value={form.message}
                  onChange={update("message")}
                  rows={5}
                  placeholder="How can we help? Festive trays, bulk orders, directions…"
                  className={`${inputCls} resize-none`}
                />
              </Field>
              <button
                type="submit"
                disabled={submitting}
                className="inline-flex items-center justify-center gap-3 bg-brand-maroon text-brand-ivory px-8 py-4 rounded-sm uppercase tracking-[0.2em] text-xs font-medium hover:bg-brand-maroon-dark transition-colors disabled:opacity-60"
              >
                {submitting ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    Sending
                  </>
                ) : (
                  "Send Message"
                )}
              </button>
            </form>
          </div>
        </div>
      </section>
    </div>
  );
}
